=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO completer with edge/level interrupts.
// Implements microarchitecture.md for interface_spec.md (task prj-c8bb158f14:rtl-implementation).
`default_nettype none

module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

  // Bits 0 .. N-1 set: the pins that exist.
  localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // ------------------------------------------------------------------
  // APB decode: zero wait states, access marks the completing cycle.
  // ------------------------------------------------------------------
  wire       access   = psel & penable;
  wire [3:0] index    = paddr[5:2];
  wire       aligned  = (paddr[1:0] == 2'b00);
  wire       hi_zero  = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire       in_range = (index <= IDX_INTR_STATUS);
  wire       mapped   = aligned & hi_zero & in_range;
  wire       wr_ok    = access & pwrite & mapped;
  wire       rd_ok    = access & ~pwrite & mapped;

  // Byte strobes expanded to bits, limited to existing pins.
  wire [31:0] wmask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

  function [31:0] merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [31:0] msk;
    begin
      merge = (old_v & ~msk) | (new_v & msk);
    end
  endfunction

  // ------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] rise_en_q;
  reg [31:0] fall_en_q;
  reg [31:0] high_en_q;
  reg [31:0] low_en_q;
  reg [31:0] int_en_q;
  reg [31:0] status_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;

  // Input widened to 32 bits, zeros above N.
  reg [31:0] in_ext;
  always @* begin
    in_ext        = 32'd0;
    in_ext[N-1:0] = gpio_in;
  end

  // ------------------------------------------------------------------
  // Next state (combinational)
  // ------------------------------------------------------------------
  wire we_data_out = wr_ok & (index == IDX_DATA_OUT);
  wire we_dir      = wr_ok & (index == IDX_DIR);
  wire we_rise     = wr_ok & (index == IDX_INTR_RISE);
  wire we_fall     = wr_ok & (index == IDX_INTR_FALL);
  wire we_high     = wr_ok & (index == IDX_INTR_HIGH);
  wire we_low      = wr_ok & (index == IDX_INTR_LOW);
  wire we_int_en   = wr_ok & (index == IDX_INTR_ENABLE);
  wire we_status   = wr_ok & (index == IDX_INTR_STATUS);

  wire [31:0] data_out_d = we_data_out ? merge(data_out_q, pwdata, wmask) : data_out_q;
  wire [31:0] dir_d      = we_dir      ? merge(dir_q,      pwdata, wmask) : dir_q;
  wire [31:0] rise_en_d  = we_rise     ? merge(rise_en_q,  pwdata, wmask) : rise_en_q;
  wire [31:0] fall_en_d  = we_fall     ? merge(fall_en_q,  pwdata, wmask) : fall_en_q;
  wire [31:0] high_en_d  = we_high     ? merge(high_en_q,  pwdata, wmask) : high_en_q;
  wire [31:0] low_en_d   = we_low      ? merge(low_en_q,   pwdata, wmask) : low_en_q;
  wire [31:0] int_en_d   = we_int_en   ? merge(int_en_q,   pwdata, wmask) : int_en_q;

  // Detection from the two samples and the enables as they are before the edge.
  wire [31:0] rise     = in_q & ~in_prev_q;
  wire [31:0] fall     = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise & rise_en_q) | (fall & fall_en_q) |
                          (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
  wire [31:0] clear    = we_status ? (pwdata & wmask) : 32'd0;
  // OR with detected last: a detection beats a clear.
  wire [31:0] status_d = (status_q & ~clear) | detected;

  // ------------------------------------------------------------------
  // Registers: synchronous active-low reset, every flop reset to zero.
  // ------------------------------------------------------------------
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'd0;
      dir_q      <= 32'd0;
      rise_en_q  <= 32'd0;
      fall_en_q  <= 32'd0;
      high_en_q  <= 32'd0;
      low_en_q   <= 32'd0;
      int_en_q   <= 32'd0;
      status_q   <= 32'd0;
      in_q       <= 32'd0;
      in_prev_q  <= 32'd0;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      rise_en_q  <= rise_en_d;
      fall_en_q  <= fall_en_d;
      high_en_q  <= high_en_d;
      low_en_q   <= low_en_d;
      int_en_q   <= int_en_d;
      status_q   <= status_d;
      in_q       <= in_ext;
      in_prev_q  <= in_q;
    end
  end

  // ------------------------------------------------------------------
  // Read multiplexer
  // ------------------------------------------------------------------
  reg [31:0] rdata;
  always @* begin
    rdata = 32'd0;
    case (index)
      IDX_DATA_OUT:    rdata = data_out_q;
      IDX_DIR:         rdata = dir_q;
      IDX_DATA_IN:     rdata = in_q;
      IDX_INTR_RISE:   rdata = rise_en_q;
      IDX_INTR_FALL:   rdata = fall_en_q;
      IDX_INTR_HIGH:   rdata = high_en_q;
      IDX_INTR_LOW:    rdata = low_en_q;
      IDX_INTR_ENABLE: rdata = int_en_q;
      IDX_INTR_STATUS: rdata = status_q;
      default:         rdata = 32'd0;
    endcase
  end

  // ------------------------------------------------------------------
  // Outputs
  // ------------------------------------------------------------------
  assign pready   = 1'b1;
  assign pslverr  = access & (~mapped | (pwrite & (index == IDX_DATA_IN)));
  assign prdata   = rd_ok ? rdata : 32'd0;
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & int_en_q);

`ifdef FORMAL
  // Design-intent assertions (not a submitted proof).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge pclk) f_past_valid <= 1'b1;

  always @(*) begin
    assert (pready == 1'b1);
    if (!access) begin
      assert (pslverr == 1'b0);
      assert (prdata == 32'd0);
    end
    assert ((data_out_q & ~PINS) == 32'd0);
    assert ((dir_q      & ~PINS) == 32'd0);
    assert ((int_en_q   & ~PINS) == 32'd0);
    assert ((status_q   & ~PINS) == 32'd0);
    assert (irq == |(status_q & int_en_q));
  end

  always @(posedge pclk) begin
    if (f_past_valid && !$past(presetn)) begin
      assert (data_out_q == 32'd0);
      assert (dir_q == 32'd0);
      assert (int_en_q == 32'd0);
      assert (status_q == 32'd0);
      assert (in_q == 32'd0);
      assert (in_prev_q == 32'd0);
      assert (irq == 1'b0);
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
// apb_gpio_tb: directed self-checking testbench for apb_gpio at N=8 and N=32.
`default_nettype none

module apb_gpio_tb;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] pins;

  wire [31:0] prdata8;
  wire [31:0] prdata32;
  wire        pready8;
  wire        pready32;
  wire        pslverr8;
  wire        pslverr32;
  wire [7:0]  gpio_out8;
  wire [7:0]  gpio_oe8;
  wire [31:0] gpio_out32;
  wire [31:0] gpio_oe32;
  wire        irq8;
  wire        irq32;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8), .pready(pready8),
    .pslverr(pslverr8), .gpio_in(pins[7:0]), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8),
    .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32), .pready(pready32),
    .pslverr(pslverr32), .gpio_in(pins), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32),
    .irq(irq32)
  );

  integer passed;
  integer failed;
  integer phase;
  integer checkno;
  integer got_nonce;
  integer k;
  reg [8*64-1:0] nonce;
  reg [31:0] m [0:8];   // model of the read/write registers, N=32 view

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // ---------------------------------------------------------------
  // Check helpers
  // ---------------------------------------------------------------
  task chk(input [31:0] got, input [31:0] exp);
    begin
      checkno = checkno + 1;
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("phase %0d check %0d: got %h, expected %h (time %0t)",
               phase, checkno, got, exp, $time);
      end
    end
  endtask

  function [31:0] bmask(input [3:0] s);
    begin
      bmask = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}};
    end
  endfunction

  task tick;
    begin
      @(negedge pclk);
    end
  endtask

  task chk_outs;
    begin
      chk({24'd0, gpio_out8}, m[0] & 32'h0000_00FF);
      chk(gpio_out32, m[0]);
      chk({24'd0, gpio_oe8}, m[1] & 32'h0000_00FF);
      chk(gpio_oe32, m[1]);
    end
  endtask

  task chk_irq(input e8, input e32);
    begin
      chk({31'd0, irq8},  {31'd0, e8});
      chk({31'd0, irq32}, {31'd0, e32});
    end
  endtask

  // All APB tasks start and end on a falling edge; the next task's setup
  // follows the completion directly (back-to-back transfers).
  task apb_wr(input [7:0] a, input [31:0] d, input [3:0] s, input e);
    begin
      paddr = a; pwdata = d; pstrb = s; pwrite = 1'b1; psel = 1'b1; penable = 1'b0;
      #1;
      chk({31'd0, pslverr8},  32'd0);
      chk({31'd0, pslverr32}, 32'd0);
      chk(prdata8,  32'd0);
      chk(prdata32, 32'd0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk({31'd0, pready8},  32'd1);
      chk({31'd0, pready32}, 32'd1);
      chk({31'd0, pslverr8},  {31'd0, e});
      chk({31'd0, pslverr32}, {31'd0, e});
      chk(prdata8,  32'd0);
      chk(prdata32, 32'd0);
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'd0; pwdata = 32'd0; paddr = 8'd0;
    end
  endtask

  task apb_rd(input [7:0] a, input [31:0] x, input e);
    begin
      paddr = a; pwdata = 32'd0; pstrb = 4'd0; pwrite = 1'b0; psel = 1'b1; penable = 1'b0;
      #1;
      chk({31'd0, pslverr8},  32'd0);
      chk({31'd0, pslverr32}, 32'd0);
      chk(prdata8,  32'd0);
      chk(prdata32, 32'd0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk({31'd0, pready8},  32'd1);
      chk({31'd0, pready32}, 32'd1);
      chk({31'd0, pslverr8},  {31'd0, e});
      chk({31'd0, pslverr32}, {31'd0, e});
      chk(prdata8,  x & 32'h0000_00FF);
      chk(prdata32, x);
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'd0; pwdata = 32'd0; paddr = 8'd0;
    end
  endtask

  task wr_rw(input [7:0] a, input [31:0] d, input [3:0] s);
    begin
      apb_wr(a, d, s, 1'b0);
      m[a[5:2]] = (m[a[5:2]] & ~bmask(s)) | (d & bmask(s));
    end
  endtask

  task rd_rw(input [7:0] a);
    begin
      apb_rd(a, m[a[5:2]], 1'b0);
    end
  endtask

  task rd_all_rw;
    begin
      rd_rw(8'h00); rd_rw(8'h04); rd_rw(8'h0C); rd_rw(8'h10);
      rd_rw(8'h14); rd_rw(8'h18); rd_rw(8'h1C);
    end
  endtask

  task rw_test(input [7:0] a);
    begin
      wr_rw(a, 32'hA5A5_5A5A, 4'hF); rd_rw(a); chk_outs;
      wr_rw(a, 32'h1234_5678, 4'h5); rd_rw(a); chk_outs;
      wr_rw(a, 32'hFFFF_0000, 4'hA); rd_rw(a); chk_outs;
      wr_rw(a, 32'hFFFF_FFFF, 4'h0); rd_rw(a); chk_outs;
      wr_rw(a, 32'hFFFF_FFFF, 4'hF); rd_rw(a); chk_outs;
      wr_rw(a, 32'h0000_0000, 4'hF); rd_rw(a); chk_outs;
    end
  endtask

  // ---------------------------------------------------------------
  // Directed sequence
  // ---------------------------------------------------------------
  initial begin
    passed = 0; failed = 0; phase = 0; checkno = 0;
    nonce = {64{8'h00}};
    got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);

    presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
    paddr = 8'd0; pwdata = 32'd0; pstrb = 4'd0; pins = 32'd0;
    for (k = 0; k < 9; k = k + 1) m[k] = 32'd0;

    // Phase 1: reset values
    phase = 1;
    tick; chk_outs; chk_irq(1'b0, 1'b0);
    tick; tick;
    presetn = 1'b1;
    rd_all_rw;
    apb_rd(8'h08, 32'd0, 1'b0);
    apb_rd(8'h20, 32'd0, 1'b0);
    chk_outs; chk_irq(1'b0, 1'b0);

    // Phase 2: read/write registers, partial strobes, bits above N, pins
    phase = 2;
    wr_rw(8'h00, 32'hA5A5_5A5A, 4'hF);
    wr_rw(8'h00, 32'h1234_5678, 4'h5);
    apb_rd(8'h00, 32'hA534_5A78, 1'b0);
    wr_rw(8'h00, 32'hFFFF_0000, 4'hA);
    apb_rd(8'h00, 32'hFF34_0078, 1'b0);
    chk_outs;
    wr_rw(8'h00, 32'h0000_0000, 4'hF);
    rw_test(8'h00);
    rw_test(8'h04);
    rw_test(8'h0C);
    rw_test(8'h10);
    rw_test(8'h14);
    rw_test(8'h1C);
    pins = 32'hFFFF_FFFF; tick; tick;
    rw_test(8'h18);
    pins = 32'h0000_0000; tick; tick;
    apb_rd(8'h20, 32'd0, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr_rw(8'h00, 32'hDEAD_BEEF, 4'hF);
    wr_rw(8'h04, 32'h0F0F_F0F0, 4'hF);
    chk_outs;

    // Phase 3: DATA_IN is read only
    phase = 3;
    pins = 32'hC3A5_0F96; tick;
    apb_rd(8'h08, 32'hC3A5_0F96, 1'b0);
    apb_wr(8'h08, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h08, 32'h0000_0000, 4'hF, 1'b1);
    apb_rd(8'h08, 32'hC3A5_0F96, 1'b0);
    rd_all_rw;
    apb_rd(8'h20, 32'd0, 1'b0);
    chk_outs;

    // Phase 4: PSLVERR policy, unmapped and aliasing addresses
    phase = 4;
    apb_rd(8'h24, 32'd0, 1'b1);
    apb_rd(8'h28, 32'd0, 1'b1);
    apb_rd(8'h3C, 32'd0, 1'b1);
    apb_rd(8'h40, 32'd0, 1'b1);
    apb_rd(8'h44, 32'd0, 1'b1);
    apb_rd(8'h60, 32'd0, 1'b1);
    apb_rd(8'h80, 32'd0, 1'b1);
    apb_rd(8'hA0, 32'd0, 1'b1);
    apb_rd(8'hFC, 32'd0, 1'b1);
    apb_rd(8'h01, 32'd0, 1'b1);
    apb_rd(8'h02, 32'd0, 1'b1);
    apb_rd(8'h03, 32'd0, 1'b1);
    apb_rd(8'h06, 32'd0, 1'b1);
    apb_rd(8'h0B, 32'd0, 1'b1);
    apb_rd(8'h21, 32'd0, 1'b1);
    apb_wr(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h4C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h5C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'hC0, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    rd_all_rw;
    apb_rd(8'h20, 32'd0, 1'b0);
    chk_outs; chk_irq(1'b0, 1'b0);

    // Phase 5a: rising edge, exact timing, fires once
    phase = 5;
    pins = 32'h0000_0000; tick; tick;
    wr_rw(8'h1C, 32'hFFFF_FFFF, 4'hF);
    wr_rw(8'h0C, 32'h8100_0003, 4'hF);
    chk_irq(1'b0, 1'b0);
    pins = 32'h8100_0001;          // driven before edge E
    tick;                          // E: sampled
    chk_irq(1'b0, 1'b0);
    tick;                          // E+1: status set
    chk_irq(1'b1, 1'b1);
    apb_rd(8'h20, 32'h8100_0001, 1'b0);
    apb_rd(8'h08, 32'h8100_0001, 1'b0);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    chk_irq(1'b0, 1'b0);
    tick; tick;
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    wr_rw(8'h0C, 32'h0000_0000, 4'hF);

    // Phase 5b: falling edge, partial write-1-to-clear
    phase = 6;
    pins = 32'h5A00_00A5; tick; tick;
    wr_rw(8'h10, 32'hFFFF_FFFF, 4'hF);
    pins = 32'h1200_0021; tick; tick;
    apb_rd(8'h20, 32'h4800_0084, 1'b0);
    chk_irq(1'b1, 1'b1);
    apb_wr(8'h20, 32'h4000_0004, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0800_0080, 1'b0);
    chk_irq(1'b1, 1'b1);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'h1, 1'b0);
    apb_rd(8'h20, 32'h0800_0000, 1'b0);
    chk_irq(1'b0, 1'b1);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'h6, 1'b0);
    apb_rd(8'h20, 32'h0800_0000, 1'b0);
    apb_wr(8'h20, 32'h0000_0000, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0800_0000, 1'b0);
    apb_wr(8'h20, 32'h0800_0000, 4'h8, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr_rw(8'h10, 32'h0000_0000, 4'hF);

    // Phase 5c: high level sets again after a clear
    phase = 7;
    wr_rw(8'h14, 32'h3000_0030, 4'hF);
    tick;
    apb_rd(8'h20, 32'h1000_0020, 1'b0);
    chk_irq(1'b1, 1'b1);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h1000_0020, 1'b0);
    pins = 32'h0000_0000; tick; tick;
    apb_rd(8'h20, 32'h1000_0020, 1'b0);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr_rw(8'h14, 32'h0000_0000, 4'hF);

    // Phase 5d: low level
    phase = 8;
    wr_rw(8'h18, 32'h8000_0081, 4'hF);
    tick;
    apb_rd(8'h20, 32'h8000_0081, 1'b0);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h8000_0081, 1'b0);
    pins = 32'h8000_0001; tick; tick;
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0080, 1'b0);
    chk_irq(1'b1, 1'b1);
    wr_rw(8'h18, 32'h0000_0000, 4'hF);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    chk_irq(1'b0, 1'b0);

    // Phase 5e: interrupt mask
    phase = 9;
    wr_rw(8'h1C, 32'h0000_0000, 4'hF);
    chk_irq(1'b0, 1'b0);
    wr_rw(8'h0C, 32'h0001_0002, 4'hF);
    pins = 32'h8001_0003; tick; tick;
    apb_rd(8'h20, 32'h0001_0002, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr_rw(8'h1C, 32'h0001_0000, 4'hF);
    chk_irq(1'b0, 1'b1);
    wr_rw(8'h1C, 32'h0000_0002, 4'hF);
    chk_irq(1'b1, 1'b1);
    wr_rw(8'h1C, 32'h0000_0000, 4'h1);
    chk_irq(1'b0, 1'b0);
    apb_rd(8'h1C, 32'h0000_0000, 1'b0);

    // Phase 5f: a detection beats a clear on the same edge
    phase = 10;
    pins = 32'h8001_0001; tick; tick;
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    pins = 32'h8001_0003;          // sampled on the setup edge, detected on the clear edge
    apb_wr(8'h20, 32'h0000_0002, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0002, 1'b0);
    apb_wr(8'h20, 32'h0000_0002, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);

    // Phase 5g: one-cycle pulse, and both edges on one pin
    phase = 11;
    wr_rw(8'h0C, 32'h0400_0004, 4'hF);
    pins = 32'h8401_0007; tick;
    pins = 32'h8001_0003; tick; tick;
    apb_rd(8'h20, 32'h0400_0004, 1'b0);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    wr_rw(8'h0C, 32'h0000_0008, 4'hF);
    wr_rw(8'h10, 32'h2000_0008, 4'hF);
    pins = 32'hA001_000B; tick; tick;
    apb_rd(8'h20, 32'h0000_0008, 1'b0);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    pins = 32'h8001_0003; tick; tick;
    apb_rd(8'h20, 32'h2000_0008, 1'b0);
    apb_wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    wr_rw(8'h0C, 32'h0000_0000, 4'hF);
    wr_rw(8'h10, 32'h0000_0000, 4'hF);

    // Phase 6: reset again with state present
    phase = 12;
    wr_rw(8'h00, 32'hFFFF_FFFF, 4'hF);
    wr_rw(8'h04, 32'h5555_AAAA, 4'hF);
    wr_rw(8'h1C, 32'hFFFF_FFFF, 4'hF);
    wr_rw(8'h14, 32'hFFFF_FFFF, 4'hF);
    tick;
    apb_rd(8'h20, 32'h8001_0003, 1'b0);
    chk_irq(1'b1, 1'b1);
    chk_outs;
    presetn = 1'b0;
    tick;
    for (k = 0; k < 9; k = k + 1) m[k] = 32'd0;
    chk_outs; chk_irq(1'b0, 1'b0);
    tick;
    chk_outs; chk_irq(1'b0, 1'b0);
    presetn = 1'b1;
    tick;
    rd_all_rw;
    apb_rd(8'h08, 32'h8001_0003, 1'b0);
    apb_rd(8'h20, 32'h0000_0000, 1'b0);
    chk_outs; chk_irq(1'b0, 1'b0);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

